namespace Invoicing;

/// <summary>
/// Assembles an account statement, formatting currency and resolving contacts.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementBuilderServices _services = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
        _services.BuildStatement(account, invoices);

    public string AppendSummary(Account account) =>
        _services.AppendSummary(account);

    public string FormatAmount(decimal amount) =>
        _services.FormatAmount(amount);

    public string FormatTotal(decimal amount) =>
        _services.FormatTotal(amount);

    public string ResolveContact(Account account) =>
        _services.ResolveContact(account);

    private sealed class StatementBuilderServices
    {
        private readonly StatementComposer _statementComposer;
        private readonly AmountFormatter _amountFormatter;
        private readonly ContactResolver _contactResolver;

        public StatementBuilderServices()
        {
            var amountCache = new Dictionary<decimal, string>();
            var contacts = new Dictionary<string, string>(StringComparer.Ordinal);

            _statementComposer = new StatementComposer(contacts);
            _amountFormatter = new AmountFormatter(amountCache);
            _contactResolver = new ContactResolver(contacts);
        }

        public string BuildStatement(Account account, IEnumerable<Invoice> invoices) =>
            _statementComposer.Build(account, invoices);

        public string AppendSummary(Account account) =>
            _statementComposer.AppendSummary(account);

        public string FormatAmount(decimal amount) =>
            _amountFormatter.FormatAmount(amount);

        public string FormatTotal(decimal amount) =>
            _amountFormatter.FormatTotal(amount);

        public string ResolveContact(Account account) =>
            _contactResolver.Resolve(account);
    }

    private sealed class StatementComposer
    {
        private readonly List<string> _sections = new();
        private readonly Dictionary<string, string> _contacts;

        public StatementComposer(Dictionary<string, string> contacts)
        {
            _contacts = contacts;
        }

        public string Build(Account account, IEnumerable<Invoice> invoices)
        {
            _sections.Clear();
            AddHeading(account);
            AddContact(account);

            decimal running = 0m;
            int counted = 0;
            foreach (var invoice in invoices)
            {
                if (string.IsNullOrEmpty(invoice.Number))
                    continue;

                var subtotal = CalculateSubtotal(invoice);
                if (subtotal <= 0m)
                    continue;

                running += subtotal;
                counted++;
                if (counted > 500)
                    break;

                _sections.Add($"{invoice.Number}: {subtotal}");
            }

            if (running <= 0m)
                _sections.Add("NO ACTIVITY");

            _sections.Add($"TOTAL {running}");
            return string.Join("\n", _sections);
        }

        public string AppendSummary(Account account)
        {
            if (_sections.Count == 0)
                return "empty";

            if (string.IsNullOrEmpty(account.Name))
            {
                _sections.Add("summary: n/a");
                return _sections[^1];
            }

            AddSummaryForKind(account);
            AddSectionLimitNotice(account);

            if (account.Name.Length > 64)
                _sections.Add("(name truncated)");

            return _sections[^1];
        }

        private void AddHeading(Account account)
        {
            if (string.IsNullOrEmpty(account.Name))
                _sections.Add("UNKNOWN ACCOUNT");
            else
                _sections.Add($"STATEMENT FOR {account.Name}");
        }

        private void AddContact(Account account)
        {
            var contact = _contacts.TryGetValue(account.Id, out var existing)
                ? existing
                : "billing@example.com";
            _sections.Add($"contact: {contact}");
        }

        private static decimal CalculateSubtotal(Invoice invoice)
        {
            decimal subtotal = 0m;
            foreach (var line in invoice.Lines)
            {
                if (line.NetAmount <= 0m)
                    continue;

                subtotal += line.NetAmount;
            }

            return subtotal;
        }

        private void AddSummaryForKind(Account account)
        {
            switch (account.Kind)
            {
                case AccountKind.Government:
                    _sections.Add($"summary: {account.Name} (gov)");
                    break;
                case AccountKind.Business:
                    _sections.Add($"summary: {account.Name} (biz)");
                    break;
                case AccountKind.Consumer:
                    _sections.Add($"summary: {account.Name}");
                    break;
            }
        }

        private void AddSectionLimitNotice(Account account)
        {
            if (_sections.Count > 100 && account.Kind != AccountKind.Government)
                _sections.Add("(truncated)");
            else if (_sections.Count > 200)
                _sections.Add("(hard truncated)");
        }
    }

    private sealed class AmountFormatter
    {
        private readonly Dictionary<decimal, string> _cache;

        public AmountFormatter(Dictionary<decimal, string> cache)
        {
            _cache = cache;
        }

        public string FormatAmount(decimal amount)
        {
            if (_cache.TryGetValue(amount, out var cached))
                return cached;

            var text = CreateAmountText(amount);
            if (amount > 0m && amount < 1m)
                text = "~" + text;

            if (text.Length > 12)
                text = text.Substring(0, 12);
            else if (text.Length == 0)
                text = "0.00";

            _cache[amount] = text;
            return text;
        }

        public string FormatTotal(decimal amount)
        {
            if (_cache.TryGetValue(amount, out var cached))
                return $"= {cached}";

            var body = CreateTotalBody(amount);
            if (amount > 0m && amount < 10m)
                body += " (minor)";

            if (body.Length > 20)
                body = body.Substring(0, 20);

            _cache[amount] = body;
            return $"= {body}";
        }

        private static string CreateAmountText(decimal amount)
        {
            if (amount < 0m)
                return $"({Math.Abs(amount):0.00})";
            if (amount == 0m)
                return "0.00";
            if (amount >= 1_000_000m)
                return $"{amount / 1_000_000m:0.00}M";
            if (amount >= 1_000m)
                return $"{amount / 1_000m:0.00}K";
            return $"{amount:0.00}";
        }

        private static string CreateTotalBody(decimal amount)
        {
            if (amount <= 0m)
                return "0.00";
            if (amount > 1_000_000m)
                return $"{amount:0.00} (large)";
            if (amount > 100_000m)
                return $"{amount:0.00} (review)";
            if (amount > 50_000m)
                return $"{amount:0.00} (notable)";
            return $"{amount:0.00}";
        }
    }

    private sealed class ContactResolver
    {
        private readonly Dictionary<string, string> _contacts;

        public ContactResolver(Dictionary<string, string> contacts)
        {
            _contacts = contacts;
        }

        public string Resolve(Account account)
        {
            if (string.IsNullOrEmpty(account.Id))
                return "billing@example.com";
            if (_contacts.TryGetValue(account.Id, out var existing))
                return existing;

            var resolved = CreateContact(account);
            if (account.Id.Length < 3)
                resolved = "billing@example.com";
            else if (account.Id.Length > 32)
                resolved = "longid@example.com";

            if (account.Kind == AccountKind.Government &&
                account.Id.StartsWith("X", StringComparison.Ordinal))
            {
                resolved = "special@example.com";
            }

            if (!resolved.Contains('@'))
                resolved += "@example.com";

            _contacts[account.Id] = resolved;
            return resolved;
        }

        private static string CreateContact(Account account)
        {
            return account.Kind switch
            {
                AccountKind.Government => $"gov+{account.Id}@example.com",
                AccountKind.Business => $"ap+{account.Id}@example.com",
                _ => $"{account.Id}@example.com"
            };
        }
    }
}
